ALTER TABLE users ADD COLUMN phone text NOT NULL DEFAULT '';
ALTER TABLE users ADD COLUMN organization text NOT NULL DEFAULT '';
ALTER TABLE users ADD COLUMN interests jsonb NOT NULL DEFAULT '[]';
ALTER TABLE users ADD COLUMN terms_accepted_at timestamptz;
ALTER TABLE users ADD COLUMN privacy_accepted_at timestamptz;
ALTER TABLE users ADD COLUMN deleted_at timestamptz;
CREATE TABLE social_accounts(provider text NOT NULL, provider_user_id text NOT NULL, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, PRIMARY KEY(provider,provider_user_id), UNIQUE(provider,user_id));
CREATE TABLE learning_daily(user_id uuid REFERENCES users, day date NOT NULL, seconds numeric NOT NULL DEFAULT 0 CHECK(seconds>=0), PRIMARY KEY(user_id,day));
CREATE TABLE document_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text UNIQUE NOT NULL CHECK(kind IN ('completion','qualification')), title text NOT NULL, issuer text NOT NULL, footer text NOT NULL DEFAULT '', version integer NOT NULL DEFAULT 1, active boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO document_templates(kind,title,issuer,footer) VALUES('completion','수료증','참조은다문화 주식회사','위 사람은 본 기관의 교육과정을 성실히 이수하였으므로 이 증서를 수여합니다.'),('qualification','자격증','참조은다문화 주식회사','관리자가 확인한 발급 기준에 따라 본 증서를 발급합니다.');
ALTER TABLE issued_documents ADD COLUMN template_id uuid REFERENCES document_templates;
ALTER TABLE issued_documents ADD COLUMN snapshot jsonb NOT NULL DEFAULT '{}';
ALTER TABLE issued_documents ADD COLUMN revoked_at timestamptz;
ALTER TABLE issued_documents ADD COLUMN revoke_reason text;
CREATE UNIQUE INDEX documents_once_idx ON issued_documents(user_id,course_id,kind) WHERE revoked_at IS NULL;
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users, title text NOT NULL,body text NOT NULL,href text NOT NULL DEFAULT '/classroom',read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE delivery_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users, channel text NOT NULL CHECK(channel IN ('email','sms','alimtalk','push')), subject text NOT NULL DEFAULT '', body text NOT NULL, payload jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','processing','sent','failed','awaiting_configuration')),attempts integer NOT NULL DEFAULT 0,last_error text,created_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz);
CREATE TABLE push_subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users,endpoint text UNIQUE NOT NULL,subscription jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE newsletters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subject text NOT NULL,body text NOT NULL,created_by uuid REFERENCES users,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE site_settings(key text PRIMARY KEY,value jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO site_settings(key,value) VALUES('contact','{"name":"참조은다문화(주)","phone":"051-558-5629","email":"chamjoeund@gmail.com","address":"부산 동래구 금강로 70, 참조은빌딩 5층·7층","privacyOfficer":"이주현"}');
CREATE TABLE site_promotions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN ('banner','popup')),title text NOT NULL,body text NOT NULL DEFAULT '',href text NOT NULL DEFAULT '/news',starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,active boolean NOT NULL DEFAULT false,CHECK(ends_at>starts_at));
CREATE TABLE video_uploads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lesson_id uuid NOT NULL REFERENCES lessons,created_by uuid NOT NULL REFERENCES users,object_key text UNIQUE NOT NULL,remote_upload_id text NOT NULL,expected_size bigint NOT NULL CHECK(expected_size>0 AND expected_size<=10737418240),reserved_bytes bigint NOT NULL,original_name text NOT NULL,status text NOT NULL DEFAULT 'uploading' CHECK(status IN ('uploading','queued','ready','failed','aborted')),created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE video_jobs ADD COLUMN upload_id uuid REFERENCES video_uploads;
ALTER TABLE video_jobs ADD COLUMN stage text NOT NULL DEFAULT 'waiting';
ALTER TABLE video_jobs ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE orders ADD COLUMN course_title text NOT NULL DEFAULT '';
ALTER TABLE orders ADD COLUMN paid_at timestamptz;
CREATE TABLE payment_events(id text PRIMARY KEY,order_id uuid REFERENCES orders,type text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid UNIQUE NOT NULL REFERENCES orders,reason text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed','failed')),requested_by uuid REFERENCES users,last_error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX notifications_user_idx ON notifications(user_id,created_at DESC);
CREATE INDEX delivery_queue_idx ON delivery_jobs(status,created_at);
